import os
from http.server import BaseHTTPRequestHandler, HTTPServer


def load_key():
    try:
        with open("/run/secrets/api_key") as f:
            return f.read().strip()
    except OSError:
        return os.environ.get("API_KEY", "")


class Uplink(BaseHTTPRequestHandler):
    def do_GET(self):
        ok = load_key().startswith("kp_live_")
        self.send_response(200)
        self.end_headers()
        self.wfile.write(b"UPLINK AUTH OK\n" if ok else b"UPLINK NO KEY\n")


HTTPServer(("0.0.0.0", 8000), Uplink).serve_forever()
